-- ============================================================
-- Settlements table
-- Stores auto-settlement records (company share + dealer margin)
-- generated by the Auto Settlements page.
-- ============================================================

CREATE TABLE settlements (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  order_id UUID REFERENCES orders(id),
  dealer_id UUID REFERENCES dealers(id),
  sr_id UUID REFERENCES user_profiles(id),
  company_amount NUMERIC(14,2) DEFAULT 0,
  dealer_margin_amount NUMERIC(14,2) DEFAULT 0,
  total_collected NUMERIC(14,2) DEFAULT 0,
  item_breakdown JSONB,
  status TEXT DEFAULT 'auto_settled',
  settled_at TIMESTAMPTZ DEFAULT NOW(),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_settlements_order ON settlements(order_id);
CREATE INDEX idx_settlements_dealer ON settlements(dealer_id);
CREATE INDEX idx_settlements_sr ON settlements(sr_id);

-- ============================================================
-- RLS alignment
-- The SPA performs client-side writes using the anon key for
-- these tables, matching the existing (permissive) state of the
-- core flow tables (orders, invoices, inventory, messages,
-- dealer_ledger, support_tickets). RLS is enabled here with no
-- policies, which blocks all writes (42501) and breaks the
-- order-to-payment flow. Disable to match the rest of the schema.
-- ============================================================

ALTER TABLE payments DISABLE ROW LEVEL SECURITY;
ALTER TABLE stock_movements DISABLE ROW LEVEL SECURITY;
ALTER TABLE notifications DISABLE ROW LEVEL SECURITY;
ALTER TABLE attendance DISABLE ROW LEVEL SECURITY;
ALTER TABLE returns DISABLE ROW LEVEL SECURITY;
ALTER TABLE crm_contacts DISABLE ROW LEVEL SECURITY;
ALTER TABLE settlements DISABLE ROW LEVEL SECURITY;
